fn render_themes(out: &mut String, st: &State) {
    let rows = listnodes(st, Kind::T, false);
    if rows.is_empty() {
        return;
    }
    out.push_str("## Themes\n\n");
    out.push_str("| ID | Title | Status | Causes work | Themed work |\n");
    out.push_str("| --- | --- | --- | --- | --- |\n");
    for n in rows {
        let cw = sorted_edge_targets(st, "causes", &n.id).join(", ");
        let mut tw_ids: Vec<String> = listnodes(st, Kind::W, false)
            .into_iter()
            .filter(|w| w.single("theme").trim() == n.id)
            .map(|w| w.id.clone())
            .collect();
        tw_ids.sort();
        let tw = tw_ids.join(", ");
        let cw = if cw.is_empty() { "\u{2013}".to_string() } else { cw };
        let tw = if tw.is_empty() { "\u{2013}".to_string() } else { tw };
        out.push_str(&format!(
            "| {} | {} | {} | {cw} | {tw} |\n",
            n.id, n.title, n.status
        ));
    }
    out.push('\n');
}

fn render_discoveries(out: &mut String, st: &State) {
    let rows = listnodes(st, Kind::Y, false);
    if rows.is_empty() {
        return;
    }
    out.push_str("## Discoveries\n\n");
    out.push_str("| ID | Title | Tags | Status |\n");
    out.push_str("| --- | --- | --- | --- |\n");
    for n in rows {
        let mut tags = n.lines("tags");
        tags.sort();
        let tags = tags.join(", ");
        out.push_str(&format!(
            "| {} | {} | {tags} | {} |\n",
            n.id, n.title, n.status
        ));
    }
    out.push('\n');
}

fn node_class(n: &Node) -> &'static str {
    match n.kind {
        Kind::G => "goal",
        Kind::A => "area",
        Kind::D => "decision",
        Kind::Q => "question",
        Kind::B => "assumption",
        Kind::T => "theme",
        Kind::Y => "discovery",
        Kind::W => {
            if n.wtype.as_deref() == Some("spike") {
                "spike"
            } else if n.status == "done" || n.status == "archived" {
                "done"
            } else if n.status == "progress" {
                "progress"
            } else if n.status == "ready" {
                "ready"
            } else if n.status == "rejected" {
                "rejected"
            } else {
                "feature"
            }
        }
    }
}

fn mermaid_safe(id: &str) -> String {
    id.replace('-', "_")
}

fn mermaid_edge_line(from: &str, to: &str, label: &str) -> String {
    let f = mermaid_safe(from);
    let t = mermaid_safe(to);
    match label {
        "blocks" => format!("  {f} ==>|{label}| {t}"),
        "targets" => format!("  {f} -.->|{label}| {t}"),
        _ => format!("  {f} -->|{label}| {t}"),
    }
}

fn render_graph(out: &mut String, st: &State) {
    out.push_str("## Dependency graph\n\n");
    out.push_str("```mermaid\n");
    out.push_str("graph TD\n");
    let cp: BTreeSet<String> = crate::algebra::critical_path(st).into_iter().collect();
    for kind in Kind::ALL {
        for n in listnodes(st, kind, false) {
            let label = n.title.replace('"', "'");
            let cls = node_class(n);
            let mut line = format!(
                "  {}[\"{}: {label}\"]:::{cls}",
                mermaid_safe(&n.id),
                n.id
            );
            if cp.contains(&n.id) {
                line.push_str(",critical");
            }
            out.push_str(&line);
            out.push('\n');
        }
    }
    let mut edges: Vec<&crate::model::Edge> = st.edges.iter().collect();
    edges.sort_by(|a, b| (&a.from, &a.label, &a.to).cmp(&(&b.from, &b.label, &b.to)));
    for e in edges {
        if !(st.nodes.contains_key(&e.from) && st.nodes.contains_key(&e.to)) {
            continue;
        }
        out.push_str(&mermaid_edge_line(&e.from, &e.to, &e.label));
        out.push('\n');
    }
    if !cp.is_empty() {
        let ids: Vec<String> = cp.iter().map(|id| mermaid_safe(id)).collect();
        out.push_str(&format!("  class {} critical\n", ids.join(",")));
    }
    out.push_str(CLASSDEF_BLOCK);
    out.push_str("```\n\n");
}

pub fn render_index(st: &State, decay: i64) -> String {
    let mut out = String::new();
    out.push_str(INDEX_BANNER);
    out.push_str("\n\n# Development dashboard\n\n");
    render_content_health(&mut out, st, decay);
    render_areas(&mut out, st);
    render_goals(&mut out, st);
    render_work(&mut out, st);
    render_decisions(&mut out, st);
    render_questions(&mut out, st);
    render_assumptions(&mut out, st);
    render_themes(&mut out, st);
    render_discoveries(&mut out, st);
    render_graph(&mut out, st);
    out
}

pub fn render_graph_section(st: &State) -> String {
    let mut out = String::new();
    render_graph(&mut out, st);
    out
}

pub fn write_index(path: &Path, st: &State, decay: i64) {
    let _ = atomic_write_same_dir(path, &render_index(st, decay));
}

pub fn cmd_render(ctx: &CliCtx, _pos: &[String], _kw: &[(String, String)]) -> OpResult {
    let st = match load(ctx, true) {
        Ok(s) => s,
        Err(e) => return e,
    };
    write_index(&ctx.indexpath(), &st, dashboard_decay_count(ctx, &st));
    OpResult::ok()
}
